input.command:
cat > /tmp/boidcheck.js <<'EOF'
const { chromium } = require('playwright');
(async () => {
  const b = await chromium.launch(); const p = await b.newPage();
  const errs = []; p.on('pageerror', e => errs.push(e.message)); p.on('console', m => m.type()==='error' && errs.push(m.text()));
  await p.goto('file://' + process.argv[2]); await p.waitForTimeout(700);
  const r = {};
  r.btn = await p.textContent('#playBtn'); r.count = await p.textContent('#count');
  await p.click('#stepBtn'); await p.mouse.click(300, 300); r.count2 = await p.textContent('#count');
  await p.click('#playBtn'); await p.waitForTimeout(800); r.btn2 = await p.textContent('#playBtn'); r.fps = await p.textContent('#fps');
  await p.fill('#speed', '3'); r.speed = await p.textContent('#speedHud');
  await p.click('#resetBtn'); r.count3 = await p.textContent('#count');
  console.log(JSON.stringify(r), 'errors:', errs); await b.close();
})();
EOF
NODE_PATH=$(npm root -g) node /tmp/boidcheck.js "$PWD/index.html" 2>&1 | tail -5

